'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './orbit-system.css'

export type OrbitSystemProps = React.ComponentPropsWithoutRef<'div'> & {
    color?: string
    /** Planet colours, one orbit each, innermost first. */
    planets?: string[]
    /** Seconds for the innermost orbit; outer orbits are slower. */
    speed?: number
    paused?: boolean
}

// Concentric orbits with planets circling at different speeds, behind centred content.
const OrbitSystem = ({ color = 'rgba(148, 163, 184, 0.25)', planets = ['#38bdf8', '#a78bfa', '#f472b6', '#fbbf24'], speed = 8, paused = false, className, style, children, ...props }: OrbitSystemProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-orbits', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-orbits-color': color, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-orbits-layer" aria-hidden="true">
            {planets.map((planet, i) => (
                <span
                    key={i}
                    className="rad-fx-orbits-ring"
                    style={{ width: `${30 + i * 18}%`, animationDuration: `${speed * (1 + i * 0.7)}s`, animationDelay: `${-i * 1.7}s`, '--rad-fx-planet': planet } as React.CSSProperties}
                >
                    <span className="rad-fx-orbits-planet" />
                </span>
            ))}
        </div>
        <div className="rad-fx-orbits-content">{children}</div>
    </div>
}

export default OrbitSystem

.rad-fx-orbits {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-orbits-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-orbits-content { position: relative; }

.rad-fx-orbits[data-state='paused'] .rad-fx-orbits-layer,
.rad-fx-orbits[data-state='paused'] .rad-fx-orbits-layer * { animation-play-state: paused !important; }

.rad-fx-orbits-ring {
    position: absolute;
    left: 50%;
    top: 50%;
    aspect-ratio: 1;
    translate: -50% -50%;
    border: 1px solid var(--rad-fx-orbits-color);
    border-radius: 50%;
    animation: rad-fx-orbits 10s linear infinite;
}

.rad-fx-orbits-planet {
    position: absolute;
    top: -5px;
    left: calc(50% - 5px);
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--rad-fx-planet);
    box-shadow: 0 0 12px 2px var(--rad-fx-planet);
}

@keyframes rad-fx-orbits { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-orbits-ring { animation: none; }
    .rad-fx-orbits-ring:nth-child(2) { transform: rotate(120deg); }
    .rad-fx-orbits-ring:nth-child(3) { transform: rotate(230deg); }
    .rad-fx-orbits-ring:nth-child(4) { transform: rotate(310deg); }
}

[data-rad-fx-motion='reduce'] .rad-fx-orbits-ring { animation: none; }
[data-rad-fx-motion='reduce'] .rad-fx-orbits-ring:nth-child(2) { transform: rotate(120deg); }
[data-rad-fx-motion='reduce'] .rad-fx-orbits-ring:nth-child(3) { transform: rotate(230deg); }
[data-rad-fx-motion='reduce'] .rad-fx-orbits-ring:nth-child(4) { transform: rotate(310deg); }
